async function refreshIntelligence(){
  if(!localView||explicitDemo)return;
  try{
    const response=await fetch('http://127.0.0.1:8768/api/intelligence',{cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(5000)});
    if(!response.ok)throw new Error('Collector unavailable');
    const state=await response.json();if(!Array.isArray(state.sources)||!Array.isArray(state.items))throw new Error('Invalid collector state');
    intelligenceState=state;intelligenceAvailable=true;
  }catch{intelligenceAvailable=false;}
  if(backendState)renderBackendNews();
}
