function renderHealthSummary(){
  if(!localView||explicitDemo)return;
  const live=healthAvailable&&healthState?.heartbeat_live&&Date.now()-healthReceivedAt<15000&&Date.now()-Date.parse(healthState.checked_at)<=30000;
  const nodes=healthState?.nodes||[],good=live?nodes.filter(n=>n.status==='healthy').length:0;
  const concerns=live?nodes.filter(n=>['down','degraded','unknown'].includes(n.status)).length:nodes.length;
  $('#health-card .metric-value').innerHTML=`${live?good:'—'} <span class="metric-dim font-sans text-caption font-normal tracking-normal text-muted">/ ${nodes.length||'—'} assessed</span>`;
  $('#health-card').dataset.status=live&&!concerns?'healthy':'stale';
  $('#health-label').textContent=live?`${concerns} need attention · ${nodes.filter(n=>n.status==='inactive').length} inactive`:'Health engine unavailable';
  $('#health-card .metric-bottom>span:last-child').textContent='Health universe ↗';
  $('#health-card .live-dot').classList.toggle('animate-pulse',!!live);
}
if(localView&&!explicitDemo){connectHealth({onState:s=>{healthState=s;healthAvailable=true;healthReceivedAt=Date.now();renderHealthSummary();},onDisconnect:()=>{healthAvailable=false;renderHealthSummary();}});setInterval(renderHealthSummary,1000);}
